-- sql/2026-10-31_dons_techniques_dd35_sp-do0.sql
-- SP-DO0 — Dons DD3.5 : « don de guerrier » et données techniques (prérequis chiffrés, niveau de lanceur de sorts)
--
-- Colonnes ajoutées à dd_dons : do_guerrier (le don peut être choisi par le guerrier en tant que don supplémentaire)
-- et les données techniques do_prereq_bba / for / dex / con / int / sag / cha et do_niv_lanceur (NULL = aucun prérequis
-- connu). Ces dernières ne sont pas affichées par défaut dans la fiche du don.
-- dd_capacites_speciales.cap_choix_guerrier : le choix de don d'une capacité (SP-CH) est limité aux dons de guerrier.
--
-- Valeurs : 92 des 300 dons DD3.5 appariés par nom à une table tierce (importée en local, absente d'ici) ; « guerrier » =
-- mention « Un guerrier peut choisir … en tant que don supplémentaire » dans NOTRE description (26) OU drapeau de la table
-- tierce (20 de plus). Aucune contradiction entre les deux sources sur les dons appariés. Dons désignés par leur NOM.
-- Pas de DELIMITER.

SET NAMES utf8mb4;
SET @rs35 := (SELECT var_id FROM dd_variables WHERE var_cat = 'ruleset' AND var_valeur = 'DD3.5' LIMIT 1);

ALTER TABLE dd_dons
  ADD COLUMN do_guerrier     TINYINT(1)       NOT NULL DEFAULT 0 COMMENT '[DD3.5] Don de guerrier : choisissable en don supplémentaire (SP-DO)',
  ADD COLUMN do_prereq_bba   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : bonus de base à l''attaque minimal',
  ADD COLUMN do_prereq_for   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Force minimale',
  ADD COLUMN do_prereq_dex   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Dextérité minimale',
  ADD COLUMN do_prereq_con   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Constitution minimale',
  ADD COLUMN do_prereq_int   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Intelligence minimale',
  ADD COLUMN do_prereq_sag   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Sagesse minimale',
  ADD COLUMN do_prereq_cha   TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : Charisme minimal',
  ADD COLUMN do_niv_lanceur  TINYINT UNSIGNED NULL COMMENT '[DD3.5] Prérequis : niveau de lanceur de sorts minimal';

ALTER TABLE dd_capacites_speciales
  ADD COLUMN cap_choix_guerrier TINYINT(1) NOT NULL DEFAULT 0
    COMMENT 'Mode don : limite le choix aux dons de guerrier (SP-DO) ; avec cap_choix_dado_id, dons de guerrier OU de cette catégorie';

UPDATE dd_dons SET do_guerrier = 0, do_prereq_bba = NULL, do_prereq_for = NULL, do_prereq_dex = NULL, do_prereq_con = NULL, do_prereq_int = NULL, do_prereq_sag = NULL, do_prereq_cha = NULL, do_niv_lanceur = NULL WHERE TRIM(do_nom) = 'Affinité magique' AND do_ruleset_var_id = @rs35;
